        {pill('扣分', minusC, '#DC2626')}
        {Math.abs(otherC) >= 0.05 && pill('其他', otherC, '#6D28D9')}
        {Math.abs(trendC) >= 0.05 && pill('趋势', trendC, '#B45309')}
        <span className="mx-0.5 text-[11px] font-black text-muted-foreground">=</span>
